#Requires -Version 7.0
[CmdletBinding(SupportsShouldProcess)]
param()
$ErrorActionPreference='Stop'
$workspace='<repo>'
$folder=Join-Path $workspace 'docs/evidence/release15/hosting-readiness'
$metadataPath=Join-Path $folder 'resume-20261031-metadata.json'
$probePath=Join-Path ([IO.File]::ReadAllText('/tmp/wordpairs-staging-dataapi-resume-directory.txt')) 'receipt.json'
$metadata=Get-Content -LiteralPath $metadataPath -Raw|ConvertFrom-Json -Depth 80
$probe=Get-Content -LiteralPath $probePath -Raw|ConvertFrom-Json -Depth 50
$target=Join-Path $folder 'resume-20261031-index.json'
function Get-Pin([string]$Path){[pscustomobject]@{path=[IO.Path]::GetRelativePath($workspace,$Path);sha256=(Get-FileHash -LiteralPath $Path).Hash;bytes=(Get-Item -LiteralPath $Path).Length}}
$summaries=@(foreach($item in $metadata.environments){
 $m=$item.metadata
 [pscustomobject]@{environment=$item.logical;projectRef=$item.supabaseProject.id;projectStatus=$item.supabaseProject.status;databaseVersion=$item.supabaseProject.database.version;migrationNames=@($item.migrations.name);migrationCount=@($item.migrations).Count;selectedRelations=@($m.relations).Count;selectedRlsEnabled=@($m.relations|Where-Object rls).Count;browserCrudPrivilegeRecords=@($m.tablePrivileges).Count;browserCrudAllowedRecords=@($m.tablePrivileges|Where-Object {$_.select -or $_.insert -or $_.update -or $_.delete}).Count;realtimePolicy=@($m.policies|Where-Object name -CEQ 'wordpairs_own_notifications');tickFunction=$m.tickFunction;cronJobs=$m.cronJobs;scheduler=$m.scheduler;vaultPresence=$m.vaultSecretPresence;latestDeployment=$item.vercelProject.latestDeployment;deployments=$item.deployments;securityAdvisories=@($item.security.lints|Select-Object name,level,count,remediation);performanceAdvisories=@($item.performance.lints|Select-Object name,level,count,remediation)}
})
$findings=@(
 [pscustomobject]@{id='PROJECT-IDENTITIES';status='PASS';detail='Connected tools freshly returned both exact Vercel project/account identities and Supabase project/name/organization bindings.'},
 [pscustomobject]@{id='MIGRATION-STATE';status='PASS';detail='Both return13 canonical baseline names/order; forward012/013 absent. Name freshness only, not fresh complete bodies.'},
 [pscustomobject]@{id='SELECTED-RLS';status='PASS';detail='All33 selected relations have RLS enabled on each project.'},
 [pscustomobject]@{id='SELECTED-BROWSER-GRANTS';status='PASS';detail='64 anon/authenticated application-table privilege records deny all CRUD on each project. Application schemas deny USAGE for browser roles.'},
 [pscustomobject]@{id='PRIVATE-POLICY-METADATA';status='PASS';detail='Exact private own-profile broadcast SELECT/authenticated predicate returned both. This is metadata only.'},
 [pscustomobject]@{id='WORKER-CONTROL-METADATA';status='PASS';detail='One existing jobID1/wordpairs-hosted-tick/1second/postgres-owned/exact command per environment. Staging active+enabled/lastStatus200; production inactive+disabled/lastStatusnull; Vault named-secret presence true both. No invocation or credential validity inferred.'},
 [pscustomobject]@{id='OWNED-STAGING-APP-FLOW';status='PASS';detail='One guestPOST200 and RealtimeGET200, exact project/profile binding, then owned-sessionDELETE204. Credentials never logged, authenticated Realtime token unused. No room or production traffic.'},
 [pscustomobject]@{id='ANONYMOUS-DATAAPI-PROBE';status='FAIL';detail='The one unsupported-schema GET with the app-returned legacy role=anon key returnedHTTP401 with no supported error code. The branch stopped without retry. This is a failed probe, not proof of broad data inaccessibility or a particular cause.'},
 [pscustomobject]@{id='DATAAPI-ALLOWLIST';status='UNKNOWN';detail='Exact exposed schemas, including vault/net exclusion, remain unverified for staging and production. Missing dependency: supported current PostgREST configuration observation or successful explicitly authorized anonymous-role schema-selection response.'},
 [pscustomobject]@{id='FORWARD-MIGRATIONS';status='UNKNOWN';detail='012privacy/013cap15 rollout not executed. Dependency: source acceptance, current RPO decision/backup, staging-first authorized migration and exact definition/history readback.'},
 [pscustomobject]@{id='HOSTED-GAME-ACCEPTANCE';status='UNKNOWN';detail='Private Realtime delivery, autonomous deadline/outbox progress and full hosted game not exercised. Dependency: accepted exact SHA deployment and owned hosted UI acceptance.'},
 [pscustomobject]@{id='CURRENT-GLOBAL-BUILD-GUARDS';status='UNKNOWN';detail='Connector does not expose current Ignored Build Step. Yesterday browser observation remains historical; root must refresh both exit0 guards before guarded one-invocation redeploy. No configuration change made.'},
 [pscustomobject]@{id='DEPLOYMENT';status='UNKNOWN';detail='Staging READY latest remains old8e2f624; production latestCANCELED and READY target-production filtered list empty. Accepted new candidate not deployed.'},
 [pscustomobject]@{id='FRESH-BACKUP-RPO';status='UNKNOWN';detail='Oct30 encrypted application snapshot/restore receipts retained but not refreshed today. Missing decision: acceptable pre-migration RPO, with fresh export if required. No new backup operation executed.'}
)
$warnings=@('Both projects retain31 RLS-without-policy INFO,7 mutable-function-search-path WARN,20 unindexed-FK INFO and1 Realtime auth-initplan WARN; production adds5 unused-index INFO. Full native details retained in metadata receipt. No remediation or security/performance acceptance inferred.')
$sourceImplications=[pscustomobject]@{
 sourcePins=@(Get-Pin (Join-Path $workspace 'src/infrastructure/realtime.ts');Get-Pin (Join-Path $workspace 'src/infrastructure/runtime.ts');Get-Pin (Join-Path $workspace 'src/web/use-room-updates.ts');Get-Pin (Join-Path $workspace 'src/app/api/realtime/route.ts'))
 observed=@('Source realtimeSettings accepts a public key by sb_publishable_ prefix or decoded role=anon; it does not verify signature, expiry, provider key activation or actual endpoint acceptance. The realtime.ts file has no diff from deployed8e2f624.','Runtime reads WORDPAIRS_SUPABASE_URL/ANON_KEY and server service/JWT settings. GET/api/realtime requires configuration plus valid application session and returns settings with a separate app-minted authenticated120second token.200 does not prove usable provider credentials.','The browser hook passes returned URL+anonKey to createClient, then supplies the separate authenticated token to realtime.setAuth and a private own-profile channel. Exact URL/profile binding was observed in this probe; legacy decoded role and ref classification are not cryptographic proof.','The anonymous PostgRESTGET used apikey and Bearer containing only the returned legacy public key. ActualHTTP401 and null safe errorcode were retained; response body discarded by design.')
 inference='Potential hosted public-key or transport/configuration problem merits explicit acceptance verification. This probe does not establish the rejection cause or whether Realtime gateway/private-channel authorization also fails; HTTPREST and Realtime paths are distinct. The authenticated application token was neither used for this probe nor validated against the provider.'
 missingEvidence=@('Current effective provider validation of the configured public key, without exposing it.','Actual private Realtime handshake/notification and token-renewal outcome on the deployed accepted candidate.','Safe response cause classification if separately authorized. No retry, env change, key creation or new hosted request in this task.')
}
$record=[pscustomobject]@{atLocal=[DateTimeOffset]::Now.ToString('o');classification='Operational prerequisite observations and one authorized owned staging app smoke, not HV or release acceptance';sessionId=$metadata.sessionId;requestId=$metadata.requestId;parentSessionId=$metadata.parentSessionId;parentRequestId=$metadata.parentRequestId;localHead=(& git -C $workspace rev-parse HEAD);metadata=Get-Pin $metadataPath;probe=Get-Pin $probePath;probeProducer=Get-Pin $probe.producer.path;probeAnalysis=Get-Pin (Join-Path (Split-Path -Parent $probePath) 'analysis.json');summaries=$summaries;findings=$findings;counts=@{pass=@($findings|Where-Object status -CEQ 'PASS').Count;fail=@($findings|Where-Object status -CEQ 'FAIL').Count;unknown=@($findings|Where-Object status -CEQ 'UNKNOWN').Count};warnings=$warnings;sideEffects=$probe.sourceSupportedSideEffects;probeFailure=$probe.failure;probeKeyClassification=$probe.keyClassification;probeSteps=$probe.steps;probeSchemaResponses=$probe.schemaProbes;scopeLimits=$metadata.limits;processNotes=@('An initial beginTurn on a new empty own cache was rejected before documented session-start bootstrap. Corrected by own Codex session-start, then began the canonical turn before provider or app work. This was invocation ordering, not evidence of a service incident.','No previous probe receipt folder/locator existed at preflight, and only inspection pwsh process was live. This run was the first actual staging probe under this branch.','PowerShell scripts parsed and PSScriptAnalyzer Warning/Error checked before actual operation; WhatIf executed. Retained original producer is unchanged; adapted producer bound only own cache/audit IDs, one unsupported schema and fresh changelog qualification.','No application source/tests/builds/models/HV, migrations, deployments, cron changes, provider settings, new keys/resources, production app traffic, denied Dashboard fallback or SQL data cleanup.');noSecretValuesInArtifacts=$true;readiness='INCOMPLETE';overallVerdict='NOT_HV';accuracy=99;completeness=96;ratingQualification='Accurate exact bounded observations with full explicit failure/unknown register. Whole hosted readiness remains unproved.'}
if(-not $PSCmdlet.ShouldProcess($target,'Write joined public-safe metadata/probe index and model-authored result')){return}
$record|Add-Member -NotePropertyName sourceImplications -NotePropertyValue $sourceImplications
if(Test-Path -LiteralPath $target){throw 'Preserve prior index'}
$retained=Join-Path $folder 'resume-20261031-index.producer.ps1';Copy-Item -LiteralPath $PSCommandPath -Destination $retained
if((Get-FileHash -LiteralPath $retained).Hash -cne (Get-FileHash -LiteralPath $PSCommandPath).Hash){throw 'Retained index producer differs'}
$record|ConvertTo-Json -Depth 70|Set-Content -LiteralPath $target
$response=(Get-Date -Format s)+' - Hosting prerequisite refresh retained in '+$target+' SHA256 '+(Get-FileHash -LiteralPath $target).Hash+'. OverallVerdict NOT_HV, PASS7/FAIL1/UNKNOWN6. All findings and qualifications follow. Accuracy99%, completeness96% for bounded operation. No release completion claim.'+"`n"+($record|ConvertTo-Json -Depth 70)
[IO.File]::WriteAllText('/tmp/wordpairs-hosting-resume-response.txt',$response)
[pscustomobject]@{index=Get-Pin $target;producer=Get-Pin $retained;counts=$record.counts;sessionId=$record.sessionId;requestId=$record.requestId}|ConvertTo-Json -Depth 6
